];

Map<String, double> calculateAverageProfit(List<Transaction> transactions) {
  Map<String, double> result = {};
  for (var transaction in transactions) {
    if (!result.containsKey(transaction.coinName)) {
      int totalProfit = 0;
      int numTransactions = 0;
      for (var t in transactions) {
        if (t.coinName == transaction.coinName) {
          totalProfit += t.profitOrLoss;
          numTransactions++;
        }
      }
      result[transaction.coinName] = totalProfit.toDouble() / numTransactions;
    }
  }
  return result;
}

