function reverseAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Initialize two empty arrays to store the nouns and reversed adjectives
  let nouns = [];
  let reversedAdjectives = [];

  // Loop through each word in the input sentence
  for (let i = 0; i < words.length; i++) {
    // If the current word is an adjective (contains at least one vowel),
    // add it to the reversedAdjectives array
    if (/\w+[aeiou]+\w*/.test(words[i])) {
      reversedAdjectives.unshift(words[i]);
    } else {
      // Otherwise, add it to the nouns array
      nouns.push(words[i]);
    }
  }

  // Concatenate the reversed adjectives and nouns arrays into a new sentence
  const reversedSentence = reversedAdjectives.concat(nouns).join(" ");

  return reversedSentence;
}

