// Recursive Fibonacci function
unsigned long fibonacci(unsigned long n, unsigned long a, unsigned long b) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

