        }
    } catch (const exception& e) {
        cerr << e.what() << endl;
        return 1;
    }

    cout << "Enter the number of Fibonacci elements to generate: ";
    cin >> numElements;
    if (numElements <= 0) {
        cerr << "Invalid input: Number of elements must be positive" << endl;
        return 1;
    }

    // Generate Fibonacci sequence
    unsigned long sequence[numElements];
    sequence[0] = a;
    sequence[1] = b;
    for (int I = 2; I < numElements; i++) {
