Here's an example of how to format orders from WooCommerce in your WordPress plugin using the provided data:

```php
function format_orders() {
    $orders = wc_get_orders();

    foreach ( $orders as $order ) {
        echo "{$order->get_date_created()->format('d/m/Y')}\n"; // Date

        echo "{$order->get_order_key()}\n"; // Order key

        // Item totals
        $item_totals = array(
            'Subtotal' => $order->get_subtotal(),
            'Shipping' => $order->get_shipping_total(),
            'Tax' => $order->get_total_tax(),
            'Total' => $order->get_total(),

            // Tax classes
            'TGC 6%' => $order->get_meta( 'tgc_6_percent', true ),
            'Remise' => $order->get_meta( 'remise', true ),
            'Location Toyota Raize Auto' => $order->get_meta( 'location_toyota_raize_auto', true ),
        );
        foreach ( $item_totals as $label => $amount ) {
            if ( $amount > 0 ) {
                echo "{$label}, {$amount},";
            }
        }
        echo "\n";

        // Credit line for customer
        $customer_total = 0;
        foreach ( $order->get_items() as $item ) {
            $customer_total += $item->get_total();
        }
        echo "Customer, {$customer_total},";

        // Items
        $items = array();
        foreach ( $order->get_items() as $item ) {
            $items[] = "{$item->get_quantity()} {$item->get_name()}, {$item->get_total()}, ";
        }
        echo implode( "\n", $items );
        echo "\n";
    }
}

