function smart_sort_array($set, $order) {
    usort($set, function($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];
        if ($order === 'desc') {
            return $ageB - $ageA;
        } else {
            return $ageA - $ageB;
        }
    });
    return $set;
}
```

